(window.TNQ=window.TNQ||[]).push({"terms":{"요수량":{"d":"작물의 건물 1kg을 생산하는 데 소비되는 수분량이다. 작은 작물일수록 수분 이용 효율이 높다.","r":[]},"광포화점":{"d":"광도가 증가해도 더 이상 광합성이 증가하지 않는 광도이다.","r":[]},"광보상점":{"d":"광합성에 의한 이산화탄소 흡수량과 호흡에 의한 방출량이 같아지는 광도이다.","r":[]},"감광성":{"d":"일장의 영향을 받아 개화가 지배되는 성질이다.","r":[]},"감온성":{"d":"온도의 영향을 받아 생육과 개화가 지배되는 성질이다.","r":[]},"기본영양생장성":{"d":"출수에 알맞은 일장과 온도에서도 일정한 영양생장이 필요한 성질.","r":["감광성","감온성"]},"수발아":{"d":"결실기에 이삭에 달린 채로 종자가 싹트는 현상이다.","r":[]},"예냉":{"d":"수확한 원예산물의 품온을 빨리 낮추어 호흡과 부패를 억제하는 처리이다.","r":[]},"큐어링":{"d":"수확 때 생긴 상처를 빨리 아물게 하는 처리이다. 감자와 고구마에 쓴다.","r":[]},"맹아":{"d":"휴면이 끝난 뒤 구근이나 덩이줄기에서 돋아나는 싹.","r":[]},"호흡비급등형":{"d":"성숙 과정에서 호흡량이 급격히 늘어나지 않는 과실이다.","r":[]},"포화용존산소량":{"d":"일정 온도에서 물에 녹을 수 있는 산소의 최대량이다. 온도가 높을수록 적어진다.","r":[]},"화채류":{"d":"꽃이나 꽃봉오리를 먹는 채소류이다. 브로콜리, 콜리플라워가 해당한다.","r":[]},"생육적온":{"d":"식물이 생육하는 데 가장 알맞은 온도이다.","r":[]},"호냉성 채소":{"d":"비교적 서늘한 온도 조건에서 잘 자라는 채소이다.","r":[]},"호온성 채소":{"d":"비교적 따뜻한 온도에서 잘 자라는 채소이다.","r":[]},"내건성":{"d":"건조한 환경에서 견디는 작물의 성질이다.","r":[]},"점적관수":{"d":"튜브의 미세한 구멍으로 물을 소량씩 흘려 근권부 토양에 집중적으로 관수하는 방법이다.","r":[]},"저면관수":{"d":"화분이나 파종상의 배수공으로 물이 스며 올라가도록 하는 관수방법이다.","r":[]},"열과":{"d":"과실의 껍질이 터지는 현상이다. 건조 후 수분이 많이 공급될 때 나타난다.","r":[]},"하고현상":{"d":"고온, 건조, 장일 조건에서 목초 등이 여름에 생육이 쇠퇴하거나 정지하는 현상이다.","r":[]},"지연형냉해":{"d":"생육 초기부터 냉온에 처해 생육이 늦어져 등숙이 불량해지는 냉해이다.","r":[]},"장해형냉해":{"d":"생식 생장기의 냉온으로 불임이 생기는 냉해이다.","r":[]},"병해형냉해":{"d":"저온에서 병에 대한 저항성이 떨어져 병 발생이 늘어나는 냉해이다.","r":[]},"C4 작물":{"d":"광합성에서 처음 만들어지는 물질이 탄소 네 개를 가진 화합물인 작물이다. 광포화점이 높은 편이다.","r":[]},"광질":{"d":"식물에 작용하는 빛의 파장 구성이다. 청색광과 적색광 등이 있다.","r":[]},"원적색광":{"d":"적색광보다 파장이 긴 적색 영역의 빛이다. 식물의 신장에 영향을 준다.","r":[]},"증산작용":{"d":"식물체 내 수분이 잎의 기공을 통해 수증기로 빠져나가는 작용이다.","r":[]},"도복":{"d":"작물이 바람이나 비로 쓰러지는 현상이다.","r":[]},"도장":{"d":"작물이 웃자라서 줄기가 가늘고 길게 자라는 현상이다.","r":[]},"왜화":{"d":"작물이 정상보다 작게 자라 키가 작아지는 현상이다.","r":[]},"탄질비":{"d":"작물체 내 탄수화물과 질소의 비율이다. 이 비율이 높으면 꽃눈분화가 촉진된다.","r":[]},"환상박피":{"d":"줄기나 가지의 껍질을 고리 모양으로 벗겨 위쪽에 탄수화물을 축적시키는 작업이다.","r":[]},"다량원소":{"d":"식물이 많은 양을 필요로 하는 필수원소이다. 질소, 인, 칼륨 등이 있다.","r":[]},"엽면시비":{"d":"비료를 물에 녹여 잎에 직접 뿌려 주는 시비 방법이다.","r":[]},"염류 집적":{"d":"시설 재배 등에서 비료 성분이 빗물에 씻기지 않아 토양 표층에 쌓이는 현상이다.","r":[]},"흡비작물":{"d":"비료 성분을 잘 흡수하는 작물이다. 염류가 쌓인 토양에서 염류를 제거하는 데 쓴다.","r":[]},"객토":{"d":"토양을 개량하려고 다른 곳의 흙을 가져다 넣는 일이다.","r":[]},"심경":{"d":"흙을 깊게 갈아엎는 작업이다. 토양의 물리성을 개선한다.","r":[]},"입단화":{"d":"토양 입자가 뭉쳐 입단을 이루는 것이다. 통기성과 보수성이 좋아진다.","r":[]},"연작장해":{"d":"같은 작물을 같은 땅에서 계속 재배할 때 생육이 나빠지는 현상이다.","r":[]},"휴면":{"d":"종자나 눈이 일시적으로 생장을 멈춘 상태이다.","r":[]},"경실종자":{"d":"종피가 단단하여 물이 잘 스며들지 않아 발아가 어려운 종자이다.","r":[]},"아브시스산":{"d":"휴면을 유도하고 기공을 닫히게 하며 탈리를 촉진하는 식물호르몬이다.","r":[]},"경화":{"d":"정식하기 전에 묘를 외부 환경에 미리 적응시키는 과정이다.","r":[]},"멀칭":{"d":"토양 표면을 덮어 잡초 억제, 토양 수분과 지온 조절을 하는 재배 방법이다.","r":[]},"휴립휴파법":{"d":"이랑을 세우고 그 이랑에 파종하는 방식이다.","r":[]},"성휴법":{"d":"이랑을 세우고 낮은 고랑에 파종하는 방식이다.","r":[]},"삽목":{"d":"식물의 잎, 줄기, 뿌리를 모체에서 분리하여 상토에 꽂아 번식시키는 방법이다.","r":[]},"분주":{"d":"뿌리 부근에서 생겨난 포기를 갈라서 심어 번식하는 방법이다.","r":[]},"취목":{"d":"가지를 모체에서 떼지 않은 채 뿌리를 내리게 한 뒤 잘라 번식시키는 방법이다.","r":[]},"고취법":{"d":"줄기나 가지를 땅에 묻을 수 없을 때 높은 곳에서 발근시켜 번식하는 취목법이다.","r":[]},"성토법":{"d":"모식물 기부에서 나온 측지에 흙을 덮어 뿌리를 내리게 하는 취목법이다.","r":[]},"인경":{"d":"잎이 변형되어 양분을 저장한 비늘줄기이다. 백합과 마늘이 대표적이다.","r":[]},"근경":{"d":"땅속에서 뿌리처럼 뻗는 줄기이다. 칸나와 독일붓꽃이 대표적이다.","r":[]},"조직배양":{"d":"무균 상태에서 인공배지에 식물 조직을 배양하여 다량의 식물을 생산하는 번식방법이다.","r":[]},"상토":{"d":"육묘나 화분 재배에 쓰는 인공 배양토이다.","r":[]},"피트모스":{"d":"이끼류가 퇴적되어 만들어진 유기질 상토 재료이다.","r":[]},"춘화":{"d":"일정 기간 저온을 겪으면 화아분화가 유기되는 현상이다.","r":[]},"이춘화":{"d":"저온 처리 뒤 고온에 노출시켜 이미 받은 저온 효과를 없애는 것이다.","r":[]},"한계일장":{"d":"개화가 일어나는 일장의 경계가 되는 길이이다.","r":[]},"종자춘화형":{"d":"종자 상태에서 저온을 받아 춘화되는 유형이다.","r":[]},"녹식물춘화형":{"d":"식물체가 어느 정도 자란 뒤 저온을 받아야 춘화되는 유형이다.","r":[]},"호흡 급등형":{"d":"성숙 과정에서 호흡량과 에틸렌 생성이 일시적으로 크게 늘어나는 과실이다.","r":[]},"수증기압포차":{"d":"원예산물 표면과 대기 사이의 수증기압 차이이다. 클수록 증산이 활발하다.","r":[]},"경종적 방제":{"d":"품종 선택이나 재배 방법의 조정으로 병해충을 막는 방제이다.","r":[]},"생물적 방제":{"d":"천적이나 미생물, 천연물질 등 살아 있는 생물이나 그 산물을 이용하는 방제이다.","r":[]},"덩굴쪼김병":{"d":"토양 전염성 진균에 의한 병이다. 대목을 사용하는 접목재배로 방제할 수 있다.","r":[]},"근두암종병":{"d":"세균에 의해 뿌리 부근 줄기에 혹이 생기는 병이다.","r":[]},"화상병":{"d":"세균에 의해 꽃, 잎, 줄기가 검게 변하며 서서히 고사하는 전염성이 강한 병이다.","r":[]},"수분수":{"d":"다른 품종의 꽃가루를 공급하기 위해 함께 심는 나무이다.","r":[]},"엽과비":{"d":"과실 하나당 잎의 수 또는 잎 면적의 비율이다.","r":[]},"순지르기":{"d":"신초의 끝을 잘라 생장을 일시적으로 억제하고 곁가지 발생을 촉진하는 작업이다.","r":[]},"벤로형":{"d":"처마가 높고 폭이 좁은 양지붕형 온실을 연결한 온실이다. 토마토와 파프리카 재배에 적합하다.","r":[]},"무적 필름":{"d":"표면장력을 낮춰 물방울이 맺히지 않도록 한 필름이다.","r":[]},"고설 재배":{"d":"양액재배 베드를 허리 높이까지 설치하는 재배 방식이다.","r":[]},"NFT재배":{"d":"베드 바닥에 기울기를 두어 얇은 막 형태의 양액이 흐르게 하고 뿌리 일부만 닿게 하는 수경재배이다.","r":[]},"생장조절물질":{"d":"식물의 생장과 발달을 조절하는 화학물질이다. 옥신, 지베렐린, 시토키닌, 에틸렌 등이 있다.","r":[]},"옥신":{"d":"극성수송을 하며 발근을 촉진하는 식물호르몬이다. 합성물질로 4-CPA, 2,4-D가 있다.","r":[]},"지베렐린":{"d":"줄기 신장과 발아를 촉진하는 식물호르몬이다. 포도의 무핵화와 과립 비대에 쓴다.","r":[]},"블라인드 현상":{"d":"장미에서 꽃눈이 생기지 않고 가지만 자라는 현상이다.","r":[]},"팬앤드패드":{"d":"젖은 패드에 공기를 통과시켜 물의 기화열로 온실 온도를 낮추는 냉방법이다.","r":[]}},"notes":{"PE 필름, PVC 필름, EVA 필름은 모두 연질필름이다":"연질필름은 가소제를 넣어 부드럽게 만든 피복재이며 세 가지 모두 이에 해당합니다.","leaf/fruit ratio":"엽과비는 과실 하나당 잎의 수를 나타내는 비율로, 영어 표현은 잎 대 과실의 비를 뜻합니다.","강풍은 매개곤충의 활동을 저하시켜 수분과 수정을 방해한다":"곤충 활동이 약해지면 꽃가루가 암술에 닿지 못해 수분이 안 되고 결국 수정도 방해받습니다.","개화기의 냉온으로 불임현상이 나타나는 냉해":"장해형냉해는 꽃 필 무렵의 저온 때문에 꽃가루가 제 기능을 못 해 열매를 못 맺는 냉해예요.","결실기에 종실이 이삭에 달린 채로 싹이 트는 것을 말한다":"수확 전 낟알이 이삭에 붙은 채 발아하는 현상으로, 품질과 수량이 떨어지는 원인이 되죠.","결실기의 벼가 우기에 도복이 되었을 때 자주 발생한다":"비가 잦은 시기에 벼가 쓰러져 이삭이 젖은 채 오래 있으면 낟알이 싹을 틔우기 쉽습니다.","고온기 수확 시 품온이 높아 바로 수송할 경우 부패하기 쉬우므로 예냉을 실시 한다":"더운 때 수확한 수박은 품온이 높아 부패하기 쉬우므로 수송 전에 예냉으로 온도를 낮추죠.","광보상점은 글록시니아보다 초롱꽃이 더 낮다":"광보상점이 낮을수록 약한 빛에서도 광합성이 호흡을 앞지르므로 초롱꽃이 그늘에 더 잘 견딥니다.","광포화점은 상추보다 토마토가 더 높다":"토마토는 상추보다 센 빛에서도 광합성이 계속 늘어나는 양지식물에 가까운 작물이죠.","기본영양생장성과 감광성이 작고 감온성이 커서":"이 유형은 일장 반응이 약하고 온도에 민감해 기온이 높을수록 출수가 빨라지는 성질입니다.","기본영양생장성과 감온성이 작고 감광성이 커서":"이 유형은 온도 반응이 약하고 낮이 짧아지는 일장 변화에 민감하게 반응하는 성질이에요.","기본영양생장성이 크고 감광성과 감온성이 작아서":"이 유형은 일장과 온도 반응이 약하고 일정한 영양생장을 거쳐야 이삭이 패는 성질이 강합니다.","기본영양생장에 지배되는 통일형 품종 벼가 여기에 해당한다":"통일형 벼는 환경보다 자체의 기본영양생장 기간에 따라 출수 시기가 정해지는 품종이에요.","높아질수록 포화용존산소량은 적어진다":"물의 온도가 오르면 녹을 수 있는 산소의 최대량이 줄어 뿌리가 쓸 산소가 부족해지기 쉽습니다.","높을수록 과실의 크기가 커진다":"과실 하나에 잎이 많이 달릴수록 광합성 산물이 더 많이 공급되어 열매가 굵어집니다.","당이 축적되지 않아 과실과 채소는 단맛이 없어지고 생육이 억제된다":"고온에서는 호흡으로 당이 소모되어 열매에 쌓이지 못하므로 맛이 밍밍하고 자람도 더뎌집니다.","만생종보다 수발아가 잘 발생한다":"조생종은 수확기가 일러 아직 덥고 비가 많은 시기와 겹치기 쉬워 수발아 위험이 큰 편이에요.","목초와 호냉성 채소의 하우스 재배시에 주로 발생한다":"서늘한 기후를 좋아하는 작물은 여름 고온에 약해 하우스 안에서 생육이 쇠퇴하는 하고현상이 생기죠.","물질이 분해될 때 암모니아에 의해 장해를 받을 수 있다":"고온에서 단백질 등이 분해되며 생긴 암모니아가 쌓이면 세포에 해를 줄 수 있어요.","뿌림 골을 만들고 그곳에 줄지어 종자를 뿌리는 방법이다":"골을 파서 그 안에 씨앗을 줄 맞춰 뿌리는 조파로, 관리와 제초 작업이 쉬워집니다.","상처를 유발하여 호흡량을 증가시킨다":"바람에 잎이 서로 부딪혀 상처가 나면 아문 자리를 만들기 위해 호흡이 늘어 양분이 소모됩니다.","상처를 통한 병해충의 발생을 촉진한다":"상처 부위는 병원균과 해충이 침입하는 통로가 되어 병해충 발생이 늘어납니다.","생육기간이 주로 감광성에 지배되며 만생종 벼가 여기에 해당한다":"만생종 벼는 가을 단일 조건이 되어야 이삭이 패므로 생육기간이 감광성에 좌우됩니다.","생육기간이 주로 감온성에 지배되며 조생종 벼가 여기에 해당한다":"조생종 벼는 온도가 오르면 일찍 이삭이 패므로 생육기간이 감온성에 따라 달라집니다.","생육 초기부터 냉온에 처하여 등숙불량이 초래되는 냉해":"지연형냉해는 초기부터 낮은 온도가 이어져 생육이 늦어지고 낟알이 여물지 못하는 냉해입니다.","세포막 지방의 유동성이 커진다":"온도가 높아지면 세포막을 이루는 지방이 묽어져 막이 헐거워지고 물질 출입이 불안정해집니다.","수매전염성 병원균의 유입 억제를 위해 급액 전에 살균한다":"물을 타고 번지는 병원균이 양액 순환계로 들어가지 못하도록 공급 전에 미리 소독해요.","수확 시 생긴 상처를 빨리 아물게 하기 위해 큐어링을 실시한다":"감자는 상처 부위로 썩음균이 들어가기 쉬워 큐어링으로 껍질에 보호층을 만들어 줍니다.","신장을 억제하고 엽육을 두껍게 한다":"자외선을 받으면 줄기가 길게 자라지 못하고 잎살이 두꺼워져 작물체가 작고 단단해집니다.","안토시아닌계 색소의 발현을 촉진한다":"자외선은 붉거나 보라색을 내는 안토시아닌 색소가 잘 만들어지게 해 과실의 착색을 돕습니다.","양액내 무기양분들은 수용성 상태로 유지하는 것이 필요하다":"뿌리는 물에 녹은 이온 상태의 양분만 흡수하므로 침전되지 않게 용해된 상태로 둬야 합니다.","요수량이 낮은 품종을 재배한다":"요수량이 낮으면 적은 물로 생산할 수 있으므로 가뭄에 강하고 물이 부족한 환경에 알맞습니다.","유기물의 과잉 소모와 질소 대사의 이상현상이 나타난다":"고온에서는 호흡이 지나쳐 저장 양분이 빨리 소모되고 단백질 합성에 필요한 질소 대사가 흐트러집니다.","이랑을 세우고 이랑에 파종하는 방식이다":"휴립휴파법은 두둑을 높이 쌓아 그 위에 씨앗을 뿌리는 방식으로, 배수와 통기가 좋아집니다.","작물의 열을 빼앗아 작물체온을 저하시킨다":"센 바람은 잎 표면의 열을 빼앗아 증산을 촉진하고 체온을 떨어뜨려 생육을 늦춥니다.","조생종보다 수발아가 덜 발생한다":"만생종은 늦게 여물어 수확기가 건조하고 서늘한 때와 맞물리므로 수발아가 상대적으로 적습니다.","질소과용이 발생하지 않도록 한다":"질소를 지나치게 주면 줄기와 잎만 웃자라 쓰러지고 병에 약해지니 알맞은 양만 줍니다.","카르티노이드계의 색소 생성을 촉진한다":"청색광은 카로티노이드 계열의 색소를 만들게 하여 열매나 잎의 노랑과 주황 발색을 돕습니다.","칼륨결핍이 발생하지 않도록 재배한다":"칼륨이 모자라면 잎 가장자리가 말라 가는 증상이 생기므로 칼륨 비료로 이를 막아야 해요.","타가수분을 위해 20 % 내외로 혼식한다":"자가불화합성 과수는 다른 품종의 꽃가루가 필요하므로 수분수를 전체의 20 % 안팎으로 섞어 심어요.","호박은 기장에 비해 요수량이 높다":"요수량이 높다는 것은 건물 하나를 만드는 데 물이 더 든다는 뜻이라, 호박이 기장보다 물을 많이 쓰는 작물이에요.","화분매개곤충의 활동을 억제한다":"바람이 세면 벌 등 꽃가루를 옮기는 곤충이 날지 못하므로 수분 기회가 줄어요.","휴면이 끝나면 싹이 자라 상품성이 저하될 수 있으므로 맹아 억제 처리를 한다":"마늘은 휴면이 끝나면 싹이 나와 품질이 떨어지므로 저장 중 싹이 트지 않도록 억제하죠."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
